function handleScoreKeydown(event){const cell=scoreCellFromElement(event.target);if(!cell)return;const modifier=event.ctrlKey||event.metaKey,keyName=event.key.toLowerCase();if(modifier&&keyName==='f'){event.preventDefault();gradeFindControl.value?.focusSearch();return}if(modifier&&keyName==='z'){event.preventDefault();event.shiftKey?redoScoreEdit():undoScoreEdit();return}if((event.ctrlKey&&keyName==='y')||(event.metaKey&&event.shiftKey&&keyName==='z')){event.preventDefault();redoScoreEdit();return}if(event.key==='Escape'){event.preventDefault();if(scoreEditing){finishScoreEdit();event.target.select?.();announceScoreSelection('Editing ended. The active score cell remains selected.')}else clearScoreSelection({blur:true});return}if(event.key==='F2'){event.preventDefault();scoreEditing=true;event.target.select?.();return}if(event.key==='Enter'){event.preventDefault();finishScoreEdit();moveScoreSelection(1,0);return}if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(event.key)&&!scoreEditing){event.preventDefault();const deltas={ArrowUp:[-1,0],ArrowDown:[1,0],ArrowLeft:[0,-1],ArrowRight:[0,1]};moveScoreSelection(...deltas[event.key],event.shiftKey)}}
