function handleScoreCopy(event){if(!scoreCellFromElement(event.target)||scoreEditing||!selectedScoreCoordinates(scoreSelection,roster.value,gradeTableModel.value.assessmentColumns).length)return;const text=selectionToTsv({selection:scoreSelection,roster:roster.value,columns:gradeTableModel.value.assessmentColumns,valueFor:score});if(event.clipboardData){event.preventDefault();event.clipboardData.setData('text/plain',text);pasteNotice.value='Selected scores copied as Excel-compatible tab-separated values.'}else writeScoreClipboardFallback(text).then(copied=>{pasteNotice.value=copied?'Selected scores copied.':'Copy was blocked by the browser. Use a supported HTTPS browser context.'})}
function handleScorePaste(event){if(!scoreCellFromElement(event.target))return;const text=event.clipboardData?.getData('text/plain');if(text===undefined||text===null)return;event.preventDefault();finishScoreEdit();const plan=planScorePaste({text,start:scoreSelection.focus,roster:roster.value,columns:gradeTableModel.value.assessmentColumns,drafts:scoreDrafts.value,valueFor:score,editable:editable.value&&!editingColumns.value&&!recoveryPending.value});pasteErrors.value=plan.errors;pasteNotice.value='';if(plan.errors.length)return;const operation=createDraftOperation('paste',plan.changes,`Paste ${plan.height} × ${plan.width} score range`);if(operation){pushScoreOperation(operation);scoreDrafts.value=applyDraftOperation(scoreDrafts.value,operation,'redo');scheduleRecoveryWrite()}if(plan.selection)setScoreSelection(plan.selection.anchor,plan.selection.focus,{focusCell:true});pasteNotice.value=operation?`${operation.changes.length} ${operation.changes.length===1?'score':'scores'} pasted as unsaved changes${plan.skippedBlanks?`; ${plan.skippedBlanks} blank ${plan.skippedBlanks===1?'cell was':'cells were'} left unchanged`:''}.`:`No score changes were needed${plan.skippedBlanks?`; ${plan.skippedBlanks} blank ${plan.skippedBlanks===1?'cell was':'cells were'} left unchanged`:''}.`}
