async function toggle(a){saving.value=true;try{await gradingService.assessmentStatus(workspace.value.sheet.id,a.id,{version:a.version,status:a.status==='active'?'archived':'active'});await openClass(workspace.value.class)}catch(e){error.value=gradingError(e)}finally{saving.value=false}}
async function saveWeights(){if(isWebsitePresentation&&dirtyScoreCount.value){error.value='Save or discard pending score changes before saving grading criteria.';return}saving.value=true;error.value='';try{await gradingService.saveWeights(workspace.value.sheet.id,activePeriod.value,weights.value.map(w=>({category:w.category,weight_percentage:Number(w.weight_percentage),version:w.version})));notice.value='Category weights saved.';await openClass(workspace.value.class)}catch(e){error.value=gradingError(e)}finally{saving.value=false}}
async function saveScores(a){const scores=workspace.value.roster.map(s=>{const v=scoreDrafts.value[key(s,a)],old=oldScore(s,a);return v===undefined?null:{enrollment_subject_id:s.enrollment_subject_id,score:Number(v),...(old?{version:old.version}:{})}}).filter(Boolean);if(!scores.length){error.value='Enter at least one changed score.';return}saving.value=true;try{await gradingService.saveScores(workspace.value.sheet.id,{assessment_id:a.id,scores});notice.value='Draft scores saved.';await openClass(workspace.value.class)}catch(e){error.value=gradingError(e)}finally{saving.value=false}}
async function saveAllScores(){if(saving.value||!dirtyScoreCount.value)return;if(invalidScoreCount.value){error.value='Correct the highlighted scores before saving.';return}const batches=collectScoreBatches({drafts:scoreDrafts.value,roster:workspace.value.roster,assessments:allScoreAssessments.value,persistedScore:oldScore});if(!batches.length)return;saving.value=true;error.value='';stopRecoveryWriteTimer();const recoveryScope=currentRecoveryScope(),activeClass=workspace.value.class,requestedCount=batches.reduce((total,batch)=>total+batch.scores.length,0);let savedCount=0;try{for(const batch of batches){const savedRows=await gradingService.saveScores(workspace.value.sheet.id,batch);const assessment=allScoreAssessments.value.find(item=>String(item.id)===String(batch.assessment_id));if(assessment&&Array.isArray(savedRows)){assessment.scores=assessment.scores||[];for(const saved of savedRows){const existing=assessment.scores.find(item=>String(item.enrollment_subject_id)===String(saved.enrollment_subject_id));existing?Object.assign(existing,saved):assessment.scores.push(saved)}}scoreDrafts.value=clearSavedScoreBatch(scoreDrafts.value,batch);savedCount+=batch.scores.length;if(recoveryEnabled.value)persistRecoveryNow()}removeGradeRecovery(sessionStorage,recoveryScope);clearScoreHistory();notice.value=`${savedCount} ${savedCount===1?'score':'scores'} saved.`;const refreshed=await openClass(activeClass);if(!refreshed)error.value=`Scores were saved, but Grade Entry could not refresh. Reload the class before continuing. ${error.value}`}catch(e){if(savedCount)clearScoreHistory();if(recoveryEnabled.value)persistRecoveryNow();const remainingCount=requestedCount-savedCount;error.value=savedCount?`${savedCount} ${savedCount===1?'score was':'scores were'} saved. ${remainingCount} ${remainingCount===1?'score remains':'scores remain'} unsaved and retained in the temporary recovery copy. Undo history was reset at the saved-data boundary. ${gradingError(e)}`:gradingError(e)}finally{saving.value=false}}
async function saveFinalWeights(){saving.value=true;try{await gradingService.saveFinalWeights(workspace.value.sheet.id,{midterm_weight:Number(workspace.value.sheet.midterm_weight),finals_weight:Number(workspace.value.sheet.finals_weight),version:workspace.value.sheet.version});notice.value='Final weighting saved.';await openClass(workspace.value.class)}catch(e){error.value=gradingError(e)}finally{saving.value=false}}
async function submitSheet(){saving.value=true;error.value='';try{await gradingService.submit(workspace.value.sheet.id,workspace.value.sheet.version);notice.value=workspace.value.sheet.status==='returned'?'Grade sheet resubmitted.':'Grade sheet submitted to Registrar.';await openClass(workspace.value.class)}catch(e){error.value=gradingError(e)}finally{saving.value=false}}
async function openReview(item){loading.value=true;try{reviewSheet.value=await gradingService.review(item.id);returnReason.value='';modal.value='review'}catch(e){error.value=gradingError(e)}finally{loading.value=false}}
async function loadReviews(){loading.value=true;error.value='';try{reviewData.value=await fetchReviewData(reviewFilters.value)}catch(e){error.value=gradingError(e)}finally{loading.value=false}}
async function reviewAction(action){saving.value=true;error.value='';try{await runWithStepUp(()=>action==='approve'?gradingService.approve(reviewSheet.value.id,reviewSheet.value.version):gradingService.returnSheet(reviewSheet.value.id,reviewSheet.value.version,returnReason.value));modal.value='';notice.value=action==='approve'?'Grade sheet approved.':'Grade sheet returned to Professor.';await loadReviews()}catch(e){if(!isStepUpCancelled(e))error.value=gradingError(e)}finally{saving.value=false}}
async function createRelease(){saving.value=true;error.value='';try{await gradingService.createRelease({...releaseForm.value,grade_sheet_ids:releaseForm.value.grade_sheet_ids.map(Number)});notice.value='Grade release scheduled.';releaseForm.value={academic_year_id:'',semester_id:'',release_at:'',grade_sheet_ids:[]};releaseData.value=await gradingService.releases()}catch(e){error.value=gradingError(e)}finally{saving.value=false}}
async function releaseNow(item){saving.value=true;try{await runWithStepUp(()=>gradingService.executeRelease(item.id));notice.value='Approved grades published.';releaseData.value=await gradingService.releases()}catch(e){if(!isStepUpCancelled(e))error.value=gradingError(e)}finally{saving.value=false}}
async function exportClass(){if(!reviewSheet.value)return;saving.value=true;error.value='';try{const response=await gradingService.classExport(reviewSheet.value.id);const url=URL.createObjectURL(response.data),a=document.createElement('a');a.href=url;a.download=response.headers['content-disposition']?.match(/filename="?([^";]+)"?/)?.[1]||'class-grade-sheet.csv';a.click();URL.revokeObjectURL(url)}catch(e){error.value=gradingError(e)}finally{saving.value=false}}
function handleBeforeUnload(event){if(!(isWebsitePresentation&&professor.value&&workspace.value&&(dirtyScoreCount.value||columnLabelChanges.value.length)))return;if(dirtyScoreCount.value&&recoveryEnabled.value)persistRecoveryNow();event.preventDefault();event.returnValue=''}
onBeforeRouteLeave(()=>{if(isWebsitePresentation&&modal.value==='excel-workflow'&&workbookHasProgress.value)return window.confirm('Leave Edit in Excel? The selected file and preview will be cleared. No grades will be changed.');if(isWebsitePresentation&&editingColumns.value){error.value='Save or cancel column changes before leaving Grade Entry.';return false}if(!(isWebsitePresentation&&professor.value&&workspace.value&&dirtyScoreCount.value))return true;if(recoveryEnabled.value&&!persistRecoveryNow()){error.value='Temporary recovery could not be stored. Keep this grade sheet open or intentionally discard the edits.';return false}return window.confirm(recoveryEnabled.value?'You have unsaved score changes. Leave while keeping this tab’s temporary recovery copy?':'You have unsaved score changes and temporary recovery is off. Leave and discard them?')})
onBeforeUnmount(()=>{if(recoveryEnabled.value&&dirtyScoreCount.value)persistRecoveryNow();stopWorkbookClock();stopRecoveryWriteTimer();clearJumpHighlight();window.removeEventListener('beforeunload',handleBeforeUnload)})
watch(()=>[route.query.view,route.query.config,route.query.institute],async ([value,config,instituteCode])=>{if(!isDesktopPresentation||professor.value||student.value)return;configurationTab.value=String(config||'')==='releases'?'releases':'scales';let tab=staffViews.includes(String(value))?String(value):'dashboard';if(tab==='configuration')tab=configurationTab.value;if(tab==='professors'&&auth.currentRole!=='Registrar Staff')tab='dashboard';staffTab.value=tab;const previousInstituteCode=selectedInstitute.value?.code;selectedInstitute.value=academicInstitutes.find(item=>item.code===String(instituteCode||''))||null;if(previousInstituteCode&&previousInstituteCode!==selectedInstitute.value?.code)reviewFilters.value={...reviewFilters.value,course_id:''};error.value='';if(['periods','professors'].includes(tab))return;loading.value=true;try{await loadStaffView(tab)}catch(e){error.value=gradingError(e)}finally{loading.value=false}})
onMounted(()=>{window.addEventListener('beforeunload',handleBeforeUnload);load()})
</script>

<template><StudentGradesView v-if="student"/><main v-else class="grading-page" :class="{'website-professor-grading':isWebsitePresentation&&professor,'desktop-registrar-grading':isDesktopPresentation&&!professor,'institute-grade-sheets':isDesktopPresentation&&!professor&&staffTab==='reviews'&&selectedInstitute}" :style="institutePageStyle">
<WebsiteModuleHeader v-if="isWebsitePresentation&&!(professor&&workspace)" eyebrow="Professor academic workspace" :title="professor?'Classes and grade entry':'Grading Management'" :description="professor?'Open an assigned class, manage assessments, and save scores in its authorized grade sheet.':'Configure periods, review submissions, and control grade publication.'"><template v-if="!professor&&staffTab==='periods'" #actions><button class="grading-button primary" @click="editPeriod()">Create Grade Period</button></template></WebsiteModuleHeader>
<InstituteHero v-if="isDesktopPresentation&&!professor&&staffTab==='reviews'&&selectedInstitute" :institute="selectedInstitute" :description="staffDescription" @back="backToInstitutes"/>
<header v-else-if="!isWebsitePresentation" class="grading-hero"><div><p class="grading-eyebrow">{{professor?'Academic records':'Registrar / Grade Management'}}</p><h1>{{professor?'Grading · My Classes':staffHeading}}</h1><p>{{professor?'Compute and submit grades from your official assigned classes.':staffDescription}}</p></div><button v-if="!professor&&staffTab==='periods'" class="grading-button primary" @click="editPeriod()">Create Grade Period</button><button v-else-if="!professor&&(staffTab==='scales'||(staffTab==='configuration'&&configurationTab==='scales'))" class="grading-button primary" @click="editScale()">Add Row</button></header>
<p v-if="notice" class="grading-alert success">{{notice}}</p><p v-if="error" class="grading-alert error" role="alert">{{error}}</p><WebsiteLoadingState v-if="isWebsitePresentation&&loading" :label="professor?'Loading grading workspace':'Loading grade periods'"/><div v-else-if="loading" class="grading-state">{{professor?'Loading grading workspace…':'Loading grade periods…'}}</div>
<template v-if="!loading"><nav v-if="!professor&&!isDesktopPresentation" class="grading-tabs" aria-label="Grading management"><button :class="{active:staffTab==='periods'}" @click="openStaffTab('periods')">Grade Periods</button><button :class="{active:staffTab==='scales'}" @click="openStaffTab('scales')">Grading Scale</button><button :class="{active:staffTab==='reviews'}" @click="openStaffTab('reviews')">Grade Approval</button><button :class="{active:staffTab==='releases'}" @click="openStaffTab('releases')">Release &amp; Schedule</button></nav><nav v-if="!professor&&configurationMode" class="registrar-configuration-tabs" aria-label="Grading configuration"><button type="button" :class="{active:configurationTab==='scales'}" :aria-current="configurationTab==='scales'?'page':undefined" @click="openConfigurationTab('scales')">Grading Scale</button><button type="button" :class="{active:configurationTab==='releases'}" :aria-current="configurationTab==='releases'?'page':undefined" @click="openConfigurationTab('releases')">Release &amp; Schedule</button></nav>
<template v-if="professor"><template v-if="!workspace"><section class="grading-toolbar"><label><span>Search classes</span><input v-model="search" type="search" placeholder="Subject or section"></label></section><div v-if="!classes.length" class="grading-state"><strong>No assigned classes</strong><span>Classes appear after Scheduling assigns an active Professor.</span></div><section v-else class="grading-class-grid"><button v-for="item in classes.filter(x=>!search||`${x.subject_code} ${x.subject_name} ${x.section}`.toLowerCase().includes(search.toLowerCase()))" :key="item.id" class="grading-class-card" @click="openClass(item)"><span>{{item.program}} · Year {{item.year_level}}</span><strong>{{item.subject_code}} — {{item.subject_name}}</strong><span>{{item.section}} · {{item.semester}}</span><span>{{item.units}} Units · {{item.student_count}} Students</span><div><em :data-state="item.schedule?.midterm_state?.state">Midterm: {{item.schedule?.midterm_state?.state||'Unavailable'}}</em><em :data-state="item.schedule?.finals_state?.state">Finals: {{item.schedule?.finals_state?.state||'Unavailable'}}</em></div></button></section></template>
<template v-else>
<header v-if="isWebsitePresentation" class="grade-entry-header"><div><button class="grading-back" type="button" @click="backToClasses">← Return to My Classes</button><div><p class="grading-eyebrow">Professor grading</p><h1>GRADE ENTRY</h1></div></div><nav class="grade-workflow-nav" aria-label="Professor grading workflow"><span aria-current="page">Grade Entry</span><button type="button" @click="openSubmissionPage">Grade Submission</button></nav></header>
<template v-else><button class="grading-back" @click="backToClasses">← Back to My Classes</button><section class="grading-summary"><div><small>Subject</small><strong>{{workspace.class.subject_code}} — {{workspace.class.subject_name}}</strong></div><div><small>Section</small><strong>{{workspace.class.section}}</strong></div><div><small>Academic term</small><strong>{{workspace.class.academic_year}} · {{workspace.class.semester}}</strong></div><div><small>Roster</small><strong>{{workspace.roster.length}} Students</strong></div><div><small>Status</small><strong class="grading-status">{{workspace.sheet.status}}</strong></div></section></template><p v-if="workspace.sheet.status==='returned'" class="grading-alert error"><strong>Returned:</strong> {{workspace.sheet.return_reason}}</p>
<RegistrarGradesheetHeader v-if="isWebsitePresentation" :class-context="workspace.class" :current-period="activePeriod" :period-state="periodState" :sheet-status="workspace.sheet.status" :student-count="workspace.roster.length" :format-date="fmt"/>
<section v-if="!isWebsitePresentation" class="grading-readiness"><div><strong>Submission readiness</strong><span>Grade data: {{readiness?.ready?'Complete':'Incomplete'}}</span><span>Submission window: {{submissionWindow}}</span><ul v-if="readiness?.errors?.length"><li v-for="item in readiness.errors" :key="item">{{item}}</li></ul></div><div class="grading-final-weights"><label>Midterm %<input v-model.number="workspace.sheet.midterm_weight" type="number" min="0" max="100" :disabled="!editable"></label><label>Finals %<input v-model.number="workspace.sheet.finals_weight" type="number" min="0" max="100" :disabled="!editable"></label><button :disabled="saving||!editable" @click="saveFinalWeights">Save final weights</button><button class="grading-button primary" :disabled="saving||!canSubmit" @click="submitSheet">{{workspace.sheet.status==='returned'?'Resubmit to Registrar':'Submit to Registrar'}}</button></div></section>

<nav class="grading-tabs"><button v-for="p in ['midterm','finals']" :key="p" :class="{active:activePeriod===p}" :disabled="isWebsitePresentation&&editingColumns" @click="reviewReadinessPeriod(p)">{{p}}</button><button type="button" :class="{active:activePeriod==='final'}" :disabled="isWebsitePresentation&&editingColumns" @click="reviewReadinessPeriod('final')">Final Grade</button></nav>
<template v-if="activePeriod!=='final'"><template v-if="isWebsitePresentation">
<section class="grade-sheet-toolbar" :data-column-mode="editingColumns" aria-label="Grade sheet tools"><GradeFindControl ref="gradeFindControl" :roster="workspace.roster" :assessments="gridAssessments" @navigate="navigateToGradeCell"/><div v-if="editingColumns" class="grading-toolbar-actions column-edit-actions"><span role="status">Column editing active</span><button type="button" class="grading-button secondary" :disabled="saving" @click="cancelColumnEditing">Cancel</button><button type="button" class="grading-button primary" :disabled="saving||hasColumnLabelErrors||!columnLabelChanges.length" @click="saveColumnChanges">{{saving?'Saving…':'Save column changes'}}</button></div><div v-else class="grading-toolbar-actions"><button class="grading-button primary" type="button" :disabled="!editable||recoveryPending||dirtyScoreCount" @click="openAssessment()">+ Add Assessment</button><button class="grading-button secondary" type="button" :disabled="!editable||!gridAssessments.length||recoveryPending" @click="beginColumnEditing">Edit Columns</button><button class="grading-button secondary" type="button" :disabled="!editable||recoveryPending||dirtyScoreCount" @click="openBulkAssessments">Bulk Entry</button><button class="grading-button secondary" type="button" @click="focusCriteria">Criteria</button><button class="grading-button secondary workbook-launch" type="button" :disabled="workbookBusy||recoveryPending" aria-haspopup="dialog" @click="openWorkbookWorkflow"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M4 3h11l5 5v13H4z"/><path d="M15 3v5h5M8 11l4 6m0-6-4 6m7-6v6"/></svg><span>Edit in Excel</span></button></div></section>
<section class="grade-recovery-option"><label><input type="checkbox" :checked="recoveryEnabled" @change="toggleRecovery"><span><strong>Temporary draft recovery</strong><small>Opt in to keep unsaved score edits in this tab’s browser session for up to 12 hours. Shared-device users should leave this off.</small></span></label><span v-if="recoveryEnabled" class="grade-recovery-enabled">On for this account</span></section>
<p v-if="recoveryStorageError" class="grade-paste-feedback error" role="alert">{{recoveryStorageError}}</p>
<div class="grade-entry-workspace-grid">
  <section class="grade-entry-sheet" aria-label="Grade entry spreadsheet">
    <section v-if="recoveryCandidate" class="grade-recovery-found" role="alert" aria-labelledby="grade-recovery-title"><div><span class="grading-eyebrow">Local recovery · not server-saved</span><h2 id="grade-recovery-title">Unsaved grading work found</h2><p><strong>{{workspace.class.subject_code}} · {{workspace.class.section}}</strong> · {{activePeriod}} · {{recoveryCandidate.edits.length}} recovered {{recoveryCandidate.edits.length===1?'edit':'edits'}} · {{recoveryTime}}</p><p>The current authoritative grade sheet was loaded first. Eligible edits can be restored as unsaved browser changes; conflicts will never overwrite newer scores.</p></div><dl><div><dt>Eligible</dt><dd>{{recoveryReview?.eligible.length||0}}</dd></div><div><dt>Conflicts</dt><dd>{{recoveryReview?.conflicts.length||0}}</dd></div></dl><ul v-if="recoveryReview?.conflicts.length" class="grade-recovery-conflicts"><li v-for="item in recoveryReview.conflicts" :key="`${item.enrollmentSubjectId}:${item.assessmentId}`"><strong>{{item.location}}</strong><span>{{item.reason}}</span></li></ul><div class="grade-recovery-actions"><button type="button" class="grading-button secondary" @click="discardRecovery">Discard Recovery</button><button type="button" class="grading-button primary" :disabled="!recoveryReview?.eligible.length" @click="restoreRecovery">{{recoveryReview?.conflicts.length?'Restore Eligible Changes':'Restore Draft'}}</button></div></section>
    <section class="grade-sheet-savebar" :data-state="invalidScoreCount?'invalid':dirtyScoreCount?'dirty':'saved'" aria-live="polite"><div class="grade-save-state-copy"><strong>{{scoreStatusMessage}}</strong><span v-if="editingColumns">Finish column editing to resume score entry.</span><span v-else-if="invalidScoreCount">Correct highlighted cells to enable Save.</span><span v-else-if="dirtyScoreCount">Review your entries, then save all pending scores together.</span><span v-else>Scores use the existing grading service and remain drafts until changed.</span></div><div class="grade-save-actions"><button type="button" class="grading-button secondary" :disabled="saving||editingColumns||!dirtyScoreCount" @click="discardScoreChanges">Discard changes</button><button type="button" class="grading-button primary" :disabled="saving||editingColumns||!editable||!dirtyScoreCount||invalidScoreCount" @click="saveAllScores">{{saving?'Saving…':'Save changes'}}</button></div></section>
    <section v-if="pasteErrors.length" class="grade-paste-feedback error" role="alert"><div><strong>Nothing was pasted</strong><span>Correct the clipboard range, then paste again. No score cells were changed.</span></div><ul><li v-for="message in pasteErrors" :key="message">{{message}}</li></ul><button type="button" aria-label="Dismiss paste errors" @click="pasteErrors=[]">×</button></section>
    <p v-else-if="pasteNotice" class="grade-paste-feedback success" role="status">{{pasteNotice}}</p>
    <p ref="scoreSelectionStatus" class="grading-visually-hidden" aria-live="polite"></p>
    <div v-if="!workspace.roster.length" class="grading-state"><strong>No enrolled Students</strong><span>The roster uses finalized Enrollment and enrolled-subject records.</span></div>
    <div v-else class="grade-sheet-scroll" role="region" aria-label="Student assessment scores and calculated grade results" tabindex="0" @keydown="handleGradeRegionKeydown">
      <table ref="scoreGrid" class="professor-grade-sheet grouped-grade-sheet registrar-inspired-grid" :class="{'is-editing-columns':editingColumns}" :style="{'--grade-table-width':`${gradeTableModel.totalWidth}px`}" :data-column-count="gradeTableModel.columnCount" @copy="handleScoreCopy" @paste="handleScorePaste" @keydown="handleScoreKeydown">
        <colgroup>
          <col v-for="column in gradeTableModel.columns" :key="column.key" :class="[`grade-column-${column.kind||'identity'}`,column.className]" :style="gradeColumnStyle(column)">
        </colgroup>
        <thead>
          <tr>
            <th class="student-information-heading" :colspan="gradeTableModel.studentInformationColumns.length" scope="colgroup">Student Information</th>
            <th v-for="group in gradeTableModel.assessmentGroups" :key="group.key" class="grade-category-heading" :colspan="group.columns.length" scope="colgroup"><span>{{group.label}}</span></th>
            <th class="grade-sheet-total" :style="gradeColumnStyle(gradeTableModel.rawTotalColumn)" rowspan="2" scope="col">{{gradeTableModel.rawTotalColumn.label}}</th>
            <th class="grade-results-heading" :colspan="gradeTableModel.resultColumns.length" scope="colgroup">Calculated Results · Read Only</th>
          </tr>
          <tr>
            <th v-for="column in gradeTableModel.studentInformationColumns" :key="column.key" :class="column.className" :style="gradeColumnStyle(column)" scope="col">{{column.label}}</th>
            <th v-for="column in gradeTableModel.assessmentColumns" :key="column.key" :style="gradeColumnStyle(column)" :data-group-start="column.groupStart||undefined" scope="col"><div class="grade-sheet-assessment"><template v-if="editingColumns"><div class="column-label-editor"><label :for="`column-label-${column.assessment.id}`" class="grading-visually-hidden">Label for {{column.assessment.label}}</label><input :id="`column-label-${column.assessment.id}`" :value="columnLabelDrafts[column.assessment.id]" maxlength="80" :aria-invalid="Boolean(columnLabelErrors[column.assessment.id])" :aria-describedby="columnLabelErrors[column.assessment.id]?`column-label-error-${column.assessment.id}`:undefined" @input="updateColumnLabel(column.assessment.id,$event.target.value)"><button type="button" class="column-remove-button" :disabled="saving||!editable" :aria-label="`Remove ${column.assessment.label} assessment column`" :title="`Remove ${column.assessment.label}`" @click="requestAssessmentArchive(column.assessment,$event)"><span aria-hidden="true">−</span></button><small v-if="columnLabelErrors[column.assessment.id]" :id="`column-label-error-${column.assessment.id}`" class="grading-field-error">{{columnLabelErrors[column.assessment.id]}}</small></div></template><span v-else :title="column.assessment.label">{{column.assessment.label}}</span><small>Maximum {{column.assessment.max_score}}</small></div></th>
            <th v-for="column in gradeTableModel.resultColumns" :key="column.key" :class="['grade-sheet-calculated',column.className]" :style="gradeColumnStyle(column)" scope="col">{{column.label}}</th>
          </tr>
        </thead>
        <tbody>
          <tr v-for="(s,i) in roster" :key="s.enrollment_subject_id">
            <td class="number" :style="gradeColumnStyle(gradeTableModel.identityColumns[0])">{{i+1}}</td>
            <td class="student-number" :style="gradeColumnStyle(gradeTableModel.identityColumns[1])"><strong>{{s.student_number}}</strong></td>
            <th class="student-name" :style="gradeColumnStyle(gradeTableModel.identityColumns[2])" scope="row">{{s.last_name}}, {{s.first_name}} {{s.middle_name||''}}</th>
            <td v-for="(column,j) in gradeTableModel.assessmentColumns" :key="column.key" class="grade-score-cell" :class="{'is-dirty':dirtyScoreKeys.has(key(s,column.assessment)),'is-invalid':scoreErrors[key(s,column.assessment)]}" :style="gradeColumnStyle(column)" :data-score-cell-key="key(s,column.assessment)" :data-enrollment-subject-id="s.enrollment_subject_id" :data-assessment-id="column.assessment.id" :data-group-start="column.groupStart||undefined" @mousedown="selectScoreCell($event,s,column,i,j)"><input type="number" min="0" :max="column.assessment.max_score" step=".01" inputmode="decimal" :disabled="!editable||editingColumns||recoveryPending" :value="score(s,column.assessment)" :data-score-row="i" :data-score-column="j" :aria-label="`${column.assessment.label} score for ${s.first_name} ${s.last_name}; maximum ${column.assessment.max_score}`" :aria-invalid="Boolean(scoreErrors[key(s,column.assessment)])" :aria-describedby="scoreErrors[key(s,column.assessment)]?`score-error-${s.enrollment_subject_id}-${column.assessment.id}`:undefined" @focus="handleScoreFocus(s,column,i,j)" @blur="finishScoreEdit" @dblclick="enterScoreEdit" @input="updateScore(s,column.assessment,$event.target.value)"><small v-if="scoreErrors[key(s,column.assessment)]" :id="`score-error-${s.enrollment_subject_id}-${column.assessment.id}`" class="grade-score-error">{{scoreErrors[key(s,column.assessment)]}}</small></td>
            <td class="grade-sheet-total" :style="gradeColumnStyle(gradeTableModel.rawTotalColumn)"><strong>{{raw(s)}}</strong></td>
            <td v-for="column in gradeTableModel.resultColumns" :key="column.key" :class="['grade-sheet-calculated',column.className]" :style="gradeColumnStyle(column)" data-readonly="true" :title="`Read-only ${column.label} result`"><strong v-if="column.key==='final-grade'">{{displayGradeValue(resultFor(s)[column.field])}}</strong><template v-else>{{displayGradeValue(resultFor(s)[column.field])}}</template></td>
          </tr>
        </tbody>
      </table>
    </div>
  </section>
  <aside ref="criteriaPanel" class="grade-entry-criteria" tabindex="-1" aria-labelledby="grading-criteria-title"><header><span>{{activePeriod}}</span><h2 id="grading-criteria-title">Grading criteria</h2></header><div class="criteria-table-wrap"><table><thead><tr><th scope="col">Category</th><th scope="col">Max score</th><th scope="col">Weight</th></tr></thead><tbody><tr v-for="item in criteriaRows" :key="item.weight.id"><th scope="row">{{item.weight.category}}</th><td>{{item.maximum_score||'—'}}</td><td><label><span class="grading-visually-hidden">{{item.weight.category}} percentage</span><input v-model.number="item.weight.weight_percentage" type="number" min="0" max="100" step=".01" :disabled="!editable"><span aria-hidden="true">%</span></label></td></tr></tbody><tfoot><tr><th scope="row">Total</th><td>—</td><td :data-valid="criteriaTotal===100">{{criteriaTotal}}%</td></tr></tfoot></table></div><button type="button" class="grading-button secondary" :disabled="saving||!editable||dirtyScoreCount" @click="saveWeights">{{saving?'Saving…':'Save criteria'}}</button></aside>
</div>
</template><template v-else><section class="grading-window" :data-state="periodState.state"><strong>{{activePeriod}}: {{periodState.state}}</strong><span>{{periodState.state==='Upcoming'?'Opens':'Deadline'}} {{fmt(periodState.state==='Upcoming'?periodState.opens_at:periodState.deadline)}}</span></section><section class="grading-weights"><label v-for="w in weights" :key="w.id"><span>{{w.category}} %</span><input v-model.number="w.weight_percentage" type="number" min="0" max="100" step=".01" :disabled="!editable"></label><button :disabled="saving||!editable" @click="saveWeights">Save weights</button></section><section class="grading-toolbar"><label><span>Search Student</span><input v-model="search" type="search" placeholder="Student number or name"></label><div class="grading-toolbar-actions"><button type="button" :disabled="!editable" @click="openBulkAssessments">Bulk Entry</button><button class="grading-button primary" :disabled="!editable" @click="openAssessment()">Add Assessment</button></div></section>
<div v-if="!workspace.roster.length" class="grading-state"><strong>No enrolled Students</strong><span>The roster uses finalized Enrollment and enrolled-subject records.</span></div><div v-else class="grading-table-wrap"><table><thead><tr><th class="sticky number">#</th><th class="sticky identity">Student</th><th v-for="a in assessments" :key="a.id"><span>{{a.label}}</span><small>{{a.category}} · /{{a.max_score}}</small><button :disabled="!editable" @click="openAssessment(a)">Edit</button><button :disabled="!editable" @click="toggle(a)">{{a.status==='active'?'Remove':'Restore'}}</button></th><th>Raw total</th></tr></thead><tbody><tr v-for="(s,i) in roster" :key="s.enrollment_subject_id"><td class="sticky number">{{i+1}}</td><td class="sticky identity"><strong>{{s.last_name}}, {{s.first_name}}</strong><small>{{s.student_number}}</small></td><td v-for="a in assessments" :key="a.id"><input v-if="a.status==='active'" type="number" min="0" :max="a.max_score" step=".01" :disabled="!editable" :value="score(s,a)" @input="scoreDrafts[key(s,a)]=$event.target.value"><span v-else>Archived</span></td><td>{{raw(s)}}</td></tr></tbody><tfoot><tr><td :colspan="2+assessments.length"></td><td><div class="grading-save-list"><button v-for="a in assessments.filter(x=>x.status==='active')" :key="a.id" :disabled="saving||!editable" @click="saveScores(a)">Save {{a.label}}</button></div></td></tr></tfoot></table></div></template></template><div v-else class="grading-table-wrap"><table><thead><tr><th>Student Number</th><th>Student Name</th><th>Midterm</th><th>Finals</th><th>Final Grade</th><th>Grade Point</th><th>Remarks</th></tr></thead><tbody><tr v-for="result in readiness?.results||[]" :key="result.enrollment_subject_id"><td>{{result.student_number}}</td><td>{{result.student_name}}</td><td>{{result.midterm_grade}}</td><td>{{result.finals_grade}}</td><td><strong>{{result.final_grade}}</strong></td><td>{{result.grade_point??'Not configured'}}</td><td>{{result.remarks??'Not configured'}}</td></tr></tbody></table></div></template></template>
<template v-else-if="staffTab==='dashboard'"><section class="registrar-institute-grid" aria-labelledby="institute-selection-title"><h2 id="institute-selection-title" class="grading-visually-hidden">Select an institute</h2><article v-for="(institute,index) in academicInstitutes" :key="institute.code" class="registrar-institute-card" :data-card="index+1"><div class="registrar-institute-mark" :data-institute="institute.code"><img v-if="instituteLogoFor(institute.code)&&!failedInstituteLogos[institute.code]" :src="instituteLogoFor(institute.code)" :alt="`${institute.name} logo`" @error="markInstituteLogoFailed(institute.code)"><span v-else :aria-label="`${institute.name} logo unavailable`">{{institute.code}}</span></div><h2>{{institute.name}}</h2><p>{{institute.programs.length}} authorized {{institute.programs.length===1?'program':'programs'}} listed in the institutional directory.</p><button type="button" @click="manageInstitute(institute)">Manage Grades <span aria-hidden="true">→</span></button></article></section><section class="registrar-grading-activity"><header><div><h2>Recent Grade Submissions</h2><p>Latest server-authoritative submissions available for Registrar review.</p></div><button type="button" @click="openStaffTab('reviews')">View all</button></header><div v-if="!reviewData.sheets.data.length" class="grading-state compact"><strong>No reviewable submissions</strong><span>Submitted grade sheets will appear here.</span></div><ul v-else><li v-for="item in reviewData.sheets.data.slice(0,4)" :key="item.id"><span class="registrar-activity-icon" aria-hidden="true">✓</span><div><strong>{{item.professor.user.profile.first_name}} {{item.professor.user.profile.last_name}}</strong><span>submitted {{item.section_subject.subject.subject_code}} · {{item.section_subject.section.section_name}}</span></div><time :datetime="item.submitted_at">{{fmt(item.submitted_at)}}</time></li></ul></section></template>
<template v-else-if="staffTab==='professors'"><section class="grading-professor-repository"><AccountProvisioningView/></section></template>
<template v-else-if="staffTab==='periods'"><div v-if="!periods.length" class="grading-state"><strong>No grade periods have been configured yet.</strong><span>Create the first term schedule to open score entry.</span></div><div v-else class="grading-table-wrap registrar-period-table"><table><thead><tr><th>Academic term</th><th>Midterm</th><th>Finals</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="item in periods" :key="item.id"><td><strong>{{item.academic_year.school_year}}</strong><small>{{item.semester.semester_name}}</small></td><td><em :data-state="item.midterm_state.state">{{item.midterm_state.state}}</em><small>{{fmt(item.midterm_opens_at)}} – {{fmt(item.midterm_deadline)}}</small></td><td><em :data-state="item.finals_state.state">{{item.finals_state.state}}</em><small>{{fmt(item.finals_opens_at)}} – {{fmt(item.finals_deadline)}}</small></td><td><strong>{{item.status}}</strong><small>Version {{item.version}}</small></td><td><div class="grading-period-actions"><button type="button" @click="editPeriod(item)">Edit</button><button v-if="item.status==='active'" type="button" @click="archive(item)">Archive</button><button type="button" class="danger" @click="confirmDeletePeriod(item)">Delete</button></div></td></tr></tbody></table></div></template>
<template v-else-if="staffTab==='scales'"><section class="grading-toolbar registrar-scale-intro"><div><strong>Authoritative grading scale</strong><span>Active ranges convert computed final percentages into official Grade Point and Remark values. Changes affect future calculations only.</span></div><button v-if="!isDesktopPresentation" class="grading-button primary" @click="editScale()">Add Range</button></section><div v-if="!scales.length" class="grading-state"><strong>No grading scale ranges configured</strong><span>Grade Point and Remark remain unconfigured until staff add active ranges.</span></div><div v-else class="grading-table-wrap registrar-scale-table"><table><thead><tr><th>Minimum Grade</th><th>Maximum Grade</th><th>Grade Point</th><th>Remark</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="item in scales" :key="item.id"><td>{{item.min_percentage}}</td><td>{{item.max_percentage}}</td><td>{{item.grade_point}}</td><td>{{item.remark}}</td><td><em :data-state="item.is_active?'active':'archived'">{{item.is_active?'Active':'Inactive'}}</em></td><td><div class="grading-period-actions"><button @click="editScale(item)">Edit</button><button :disabled="saving" @click="toggleScale(item)">{{item.is_active?'Deactivate':'Activate'}}</button></div></td></tr></tbody></table></div></template>
<template v-else-if="staffTab==='reviews'"><section class="grading-summary registrar-review-summary"><div><small>Pending Review</small><strong>{{reviewData.summary.pending_review}}</strong></div><div><small>Approved</small><strong>{{reviewData.summary.approved}}</strong></div><div><small>Published</small><strong>{{reviewData.summary.published}}</strong></div></section><form class="grading-review-filters registrar-review-filters" @submit.prevent="loadReviews"><label class="registrar-review-search">Search<input v-model="reviewFilters.search" type="search" placeholder="Course, professor, or section"></label><label>Academic Year<select v-model="reviewFilters.academic_year_id"><option value="">All years</option><option v-for="y in options.academic_years" :key="y.id" :value="y.id">{{y.school_year}}</option></select></label><label>Status<select v-model="reviewFilters.status"><option value="">All statuses</option><option value="submitted">Submitted</option><option value="approved">Approved</option><option value="published">Published</option></select></label><details><summary>More filters</summary><div><label>Semester<select v-model="reviewFilters.semester_id"><option value="">All</option><option v-for="s in options.semesters" :key="s.id" :value="s.id">{{s.semester_name}}</option></select></label><label>Program<select v-model="reviewFilters.course_id"><option value="">All</option><option v-for="c in instituteCourseOptions" :key="c.id" :value="c.id">{{c.course_code}}</option></select></label><label>Year Level<select v-model="reviewFilters.year_level"><option value="">All</option><option v-for="y in [1,2,3,4]" :key="y" :value="y">Year {{y}}</option></select></label><label>Section<select v-model="reviewFilters.section_id"><option value="">All</option><option v-for="s in options.sections" :key="s.id" :value="s.id">{{s.section_name}}</option></select></label><label>Subject<select v-model="reviewFilters.subject_id"><option value="">All</option><option v-for="s in options.subjects" :key="s.id" :value="s.id">{{s.subject_code}}</option></select></label><label>Professor<select v-model="reviewFilters.professor_id"><option value="">All</option><option v-for="p in options.professors" :key="p.id" :value="p.id">{{p.user.profile.first_name}} {{p.user.profile.last_name}}</option></select></label></div></details><button class="grading-button primary">Search</button></form><div v-if="instituteListingUnavailable" class="grading-state registrar-institute-unavailable"><strong>Institute listing unavailable</strong><span>{{instituteListingUnavailable}}</span></div><div v-else-if="!reviewData.sheets.data.length" class="grading-state"><strong>No submitted grade sheets match the current filters.</strong><span>Submitted, approved, and published sheets appear here.</span></div><div v-else class="grading-table-wrap registrar-review-table"><table><thead><tr><th>Sem</th><th>Date Submitted</th><th>Professor</th><th>Course</th><th>Section</th><th>Students</th><th>Status</th><th>Action</th></tr></thead><tbody v-for="group in reviewGroups" :key="group.year"><tr class="registrar-year-group"><th colspan="8" scope="rowgroup">{{group.year?`${group.year}${group.year===1?'st':group.year===2?'nd':group.year===3?'rd':'th'} Year`:'Year level unavailable'}} <small>{{group.sheets.length}} {{group.sheets.length===1?'submission':'submissions'}}</small></th></tr><tr v-for="item in group.sheets" :key="item.id"><td>{{item.section_subject.section.semester?.semester_order||'—'}}</td><td>{{fmt(item.submitted_at)}}</td><td>{{item.professor.user.profile.first_name}} {{item.professor.user.profile.last_name}}</td><td><strong>{{item.section_subject.subject.subject_code}}</strong><small>{{item.section_subject.subject.subject_name}}</small></td><td>{{item.section_subject.section.section_name}}</td><td>{{item.latest_submission?.students_count||0}}</td><td><em :data-state="item.status">{{item.status}}</em></td><td><button class="registrar-review-action" @click="openReview(item)">Review</button></td></tr></tbody></table></div></template>
<template v-else><form class="grading-release-form" @submit.prevent="createRelease"><h2>Schedule approved grades</h2><label>Academic Year<select v-model="releaseForm.academic_year_id" required><option disabled value="">Select</option><option v-for="y in options.academic_years" :key="y.id" :value="y.id">{{y.school_year}}</option></select></label><label>Semester<select v-model="releaseForm.semester_id" required><option disabled value="">Select</option><option v-for="s in options.semesters" :key="s.id" :value="s.id">{{s.semester_name}}</option></select></label><label>Release date and time<input v-model="releaseForm.release_at" type="datetime-local" required></label><fieldset><legend>Approved grade sheets</legend><label v-for="sheet in releaseData.approved_sheets" :key="sheet.id"><input v-model="releaseForm.grade_sheet_ids" type="checkbox" :value="sheet.id"> {{sheet.section_subject.subject.subject_code}} · {{sheet.section_subject.section.section_name}}</label><p v-if="!releaseData.approved_sheets.length">No approved grade sheets are ready for release.</p></fieldset><button class="grading-button primary" :disabled="saving||!releaseForm.grade_sheet_ids.length">Create Release Schedule</button></form><div v-if="!releaseData.schedules.data.length" class="grading-state"><strong>No release schedules</strong><span>Approved sheets remain private until scheduled and released.</span></div><div v-else class="grading-table-wrap"><table><thead><tr><th>Term</th><th>Release time</th><th>Grade sheets</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="item in releaseData.schedules.data" :key="item.id"><td>{{item.academic_year.school_year}} · {{item.semester.semester_name}}</td><td>{{fmt(item.release_at)}}</td><td>{{item.items.length}}</td><td><em :data-state="item.status">{{item.status}}</em></td><td><button v-if="item.status==='scheduled'" :disabled="saving" @click="releaseNow(item)">Release Now</button></td></tr></tbody></table></div></template></template>

<div v-if="modal" class="grading-modal-backdrop" @click.self="closeModal"> <section ref="modalDialog" class="grading-modal" :class="{'workbook-workflow-modal':modal==='excel-workflow','grading-scale-modal':modal==='scale'}" role="dialog" aria-modal="true" aria-labelledby="grading-modal-title" @keydown="handleModalKeydown">
<header><h2 id="grading-modal-title">{{modal==='period'?(editingPeriod?'Edit Grade Period':'Create Grade Period'):modal==='scale'?(editingScale?'Edit Grading Scale Range':'Add Grading Scale Range'):modal==='delete-period'?'Delete Grade Period':modal==='archive-assessment'?'Remove Assessment Column':modal==='review'?'Review Grade Sheet':modal==='bulk-assessments'?'Bulk Assessment Entry':modal==='excel-workflow'?'Edit in Excel':(editingAssessment?'Edit Assessment':'Add Assessment')}}</h2><button :class="{'workbook-close':modal==='excel-workflow'}" aria-label="Close dialog" @click="closeModal">×</button></header>
<form v-if="modal==='period'" @submit.prevent="savePeriod"><label><span>School Year</span><select v-model="periodForm.academic_year_id" required><option disabled value="">Select</option><option v-for="y in options.academic_years" :key="y.id" :value="y.id">{{y.school_year}}</option></select><small v-if="periodErrors.academic_year_id" class="grading-field-error">{{periodErrors.academic_year_id[0]}}</small></label><label><span>Semester</span><select v-model="periodForm.semester_id" required><option disabled value="">Select</option><option v-for="s in options.semesters" :key="s.id" :value="s.id">{{s.semester_name}}</option></select><small v-if="periodErrors.semester_id" class="grading-field-error">{{periodErrors.semester_id[0]}}</small></label><label><span>Midterm opens</span><input v-model="periodForm.midterm_opens_at" type="datetime-local" required><small v-if="periodErrors.midterm_opens_at" class="grading-field-error">{{periodErrors.midterm_opens_at[0]}}</small></label><label><span>Midterm deadline</span><input v-model="periodForm.midterm_deadline" type="datetime-local" required><small v-if="periodErrors.midterm_deadline" class="grading-field-error">{{periodErrors.midterm_deadline[0]}}</small></label><label><span>Finals opens</span><input v-model="periodForm.finals_opens_at" type="datetime-local" required><small v-if="periodErrors.finals_opens_at" class="grading-field-error">{{periodErrors.finals_opens_at[0]}}</small></label><label><span>Finals deadline</span><input v-model="periodForm.finals_deadline" type="datetime-local" required><small v-if="periodErrors.finals_deadline" class="grading-field-error">{{periodErrors.finals_deadline[0]}}</small></label><footer><button type="button" @click="modal=''">Cancel</button><button class="grading-button primary" :disabled="saving">Save Period</button></footer></form>
<form v-else-if="modal==='scale'" class="grading-scale-form" @submit.prevent="saveScale">
  <div class="grading-scale-percentage-row">
    <label><span>Minimum percentage</span><input v-model.number="scaleForm.min_percentage" type="number" min="0" max="100" step=".01" required><small v-if="scaleErrors.min_percentage" class="grading-field-error">{{scaleErrors.min_percentage[0]}}</small></label>
    <label><span>Maximum percentage</span><input v-model.number="scaleForm.max_percentage" type="number" min="0" max="100" step=".01" required><small v-if="scaleErrors.max_percentage" class="grading-field-error">{{scaleErrors.max_percentage[0]}}</small></label>
  </div>
  <div class="grading-scale-detail-row">
    <label><span>Grade Point</span><select v-if="isDesktopPresentation" v-model="scaleForm.grade_point" required aria-describedby="grade-point-help"><option disabled value="">Select grade point</option><option v-if="unsupportedGradePoint" :value="unsupportedGradePoint" disabled>Previously saved: {{unsupportedGradePoint}} (unsupported)</option><option v-for="point in gradePointOptions" :key="point" :value="point">{{point}}</option></select><input v-else v-model.number="scaleForm.grade_point" type="number" step=".01" required><small id="grade-point-help" :class="{'grading-field-error':scaleErrors.grade_point}">{{scaleErrors.grade_point?.[0]||'Choose an approved grade-point value.'}}</small></label>
    <label><span>Remark</span><select v-if="isDesktopPresentation" v-model="scaleForm.remark" required><option disabled value="">Select remark</option><option v-if="scaleForm.remark && !GRADE_REMARK_OPTIONS.includes(scaleForm.remark)" :value="scaleForm.remark" :disabled="!isSupportedGradeRemark(scaleForm.remark)">{{isSupportedGradeRemark(scaleForm.remark)?scaleForm.remark.toUpperCase():`Previously saved: ${scaleForm.remark} (unsupported)`}}</option><option v-for="remark in GRADE_REMARK_OPTIONS" :key="remark" :value="remark">{{remark}}</option></select><input v-else v-model.trim="scaleForm.remark" maxlength="80" required><small v-if="scaleErrors.remark" class="grading-field-error">{{scaleErrors.remark[0]}}</small></label>
  </div>
  <label class="grading-scale-active"><input v-model="scaleForm.is_active" type="checkbox"><span><strong>Active range</strong><small>Use this range in future grade calculations.</small></span></label>
  <footer><button type="button" @click="closeModal">Cancel</button><button class="grading-button primary" :disabled="saving">{{saving?'Saving…':'Save Range'}}</button></footer>
</form>
<div v-else-if="modal==='delete-period'" class="grading-delete-confirmation"><p>Delete <strong>{{periodToDelete?.academic_year?.school_year}} · {{periodToDelete?.semester?.semester_name}}</strong>?</p><p>Deletion succeeds only when no grading activity exists for this term. Existing grading history will never be removed.</p><footer><button type="button" @click="modal='';periodToDelete=null">Cancel</button><button type="button" class="grading-button danger" :disabled="saving" @click="deletePeriod">Delete unused period</button></footer></div>
<div v-else-if="modal==='archive-assessment'" class="grading-delete-confirmation"><p>Remove <strong>{{assessmentToArchive?.label}}</strong> from the active grade sheet?</p><p>This archives and hides the assessment column. Existing student scores remain stored and are not deleted. Removing it may make the grade sheet incomplete until submission requirements are satisfied.</p><footer><button type="button" @click="closeModal">Cancel</button><button ref="archiveConfirmButton" type="button" class="grading-button danger" :disabled="saving" @click="archiveAssessment">{{saving?'Archiving…':'Archive assessment'}}</button></footer></div>
<form v-else-if="modal==='bulk-assessments'" class="grading-bulk-assessment" @submit.prevent="saveBulkAssessments"><p>Paste one assessment per line as <strong>Label | Category | Maximum score</strong>. Tab-separated columns are also supported.</p><textarea aria-label="Paste assessment rows" v-model="bulkAssessmentText" rows="7" placeholder="Quiz 1 | Quiz | 20
Laboratory 1 | Activity | 50"></textarea><button type="button" :disabled="saving" @click="previewBulkAssessments">Parse &amp; Preview</button><ul v-if="bulkAssessmentErrors.length" class="grading-bulk-errors"><li v-for="item in bulkAssessmentErrors" :key="item">{{item}}</li></ul><div v-if="bulkAssessmentRows.length" class="grading-table-wrap"><table><thead><tr><th>Label</th><th>Category</th><th>Max score</th><th>Order</th></tr></thead><tbody><tr v-for="(row,index) in bulkAssessmentRows" :key="index"><td><input v-model.trim="row.label" :aria-label="`Assessment ${index + 1} label`" maxlength="80" required></td><td><select v-model="row.category" :aria-label="`Assessment ${index + 1} category`"><option v-for="category in ASSESSMENT_CATEGORIES" :key="category">{{category}}</option></select></td><td><input v-model.number="row.max_score" :aria-label="`Assessment ${index + 1} maximum score`" type="number" min="0.01" max="999999.99" step="0.01" required></td><td><input v-model.number="row.display_order" :aria-label="`Assessment ${index + 1} display order`" type="number" min="1" max="65535" required></td></tr></tbody></table></div><footer><button type="button" @click="modal=''">Cancel</button><button class="grading-button primary" :disabled="saving||!bulkAssessmentRows.length||bulkAssessmentErrors.length">{{saving?'Saving…':`Save ${bulkAssessmentRows.length} Assessments`}}</button></footer></form>
<section v-else-if="modal==='excel-workflow'" class="workbook-workflow">
  <nav class="workbook-progress" aria-label="Edit in Excel progress">
    <button v-for="(item,index) in workbookSteps" :key="item[0]" type="button" :class="{active:workbookStep===index+1,complete:workbookReachedStep>index+1}" :aria-current="workbookStep===index+1?'step':undefined" :disabled="index+1>workbookReachedStep||workbookBusy" @click="goWorkbookStep(index+1)"><span>{{index+1}}</span><strong>{{item[0]}}</strong></button>
  </nav>
  <div class="workbook-context" aria-label="Current gradesheet"><span><strong>{{workspace.class.subject_code}}</strong> · {{workspace.class.subject_name}}</span><span>{{workspace.class.section}}</span><span>{{activePeriod==='midterm'?'Midterm':'Finals'}}</span></div>
  <div v-if="workbookHasPendingBrowserChanges" class="workbook-pending-warning" role="alert"><strong>Unsaved Grade Entry changes detected</strong><p>Close this dialog, then save or intentionally discard the pending browser edits before downloading or uploading a workbook. Your edits have not been discarded.</p></div>

  <section v-if="workbookStep===1" class="workbook-step">
    <div><span class="workbook-step-kicker">Step 1 of 5</span><h3 tabindex="-1" data-workbook-step-heading>Download Gradesheet</h3><p>Download the current {{activePeriod}} workbook for {{workspace.class.subject_code}} — {{workspace.class.section}}. It contains the authorized Student roster, active assessments, and server-saved scores.</p></div>
    <div v-if="workbookDownloadError" class="workbook-inline-error" role="alert">{{workbookDownloadError}}</div>
    <button type="button" class="grading-button primary workbook-download" :disabled="workbookBusy||workbookHasPendingBrowserChanges" @click="exportWorkbook"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M12 3v12m-4-4 4 4 4-4M5 19h14"/></svg>{{workbookBusy?'Preparing download…':'Download Excel Gradesheet'}}</button>
    <p v-if="workbookDownloaded" class="workbook-success" role="status">Download started. Open the saved `.xlsx` file in Microsoft Excel.</p>
    <footer><button type="button" :disabled="workbookBusy" @click="requestWorkbookClose">Cancel</button><button type="button" class="grading-button primary" :disabled="!workbookDownloaded||workbookBusy" @click="advanceWorkbookStep(2)">Continue</button></footer>
  </section>

  <section v-else-if="workbookStep===2" class="workbook-step">
    <div><span class="workbook-step-kicker">Step 2 of 5</span><h3 tabindex="-1" data-workbook-step-heading>Edit in Microsoft Excel</h3><p>Open the downloaded workbook in desktop Microsoft Excel. CDM Portal does not synchronize changes automatically.</p></div>
    <ul class="workbook-guidance"><li>Only the pale-green assessment score cells are editable.</li><li>Leave a score cell blank to keep the current server score unchanged.</li><li>Enter <strong>0</strong> to propose an explicit zero score.</li><li>Save the edited workbook as an `.xlsx` file before returning here.</li></ul>
    <footer><button type="button" @click="goWorkbookStep(1)">Back</button><button type="button" class="grading-button primary" @click="advanceWorkbookStep(3)">I saved the workbook</button></footer>
  </section>

  <section v-else-if="workbookStep===3" class="workbook-step">
    <div><span class="workbook-step-kicker">Step 3 of 5</span><h3 tabindex="-1" data-workbook-step-heading>Upload Edited File</h3><p>Upload the saved CDM Portal `.xlsx` workbook. It will be validated before any score can be applied.</p></div>
    <input ref="workbookInput" class="grading-visually-hidden" type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" tabindex="-1" @change="previewWorkbook">
    <div class="workbook-dropzone" :class="{dragging:workbookDragActive}" role="button" tabindex="0" :aria-disabled="workbookBusy||workbookHasPendingBrowserChanges" @click="chooseWorkbook" @keydown.enter.prevent="chooseWorkbook" @keydown.space.prevent="chooseWorkbook" @dragenter.prevent="workbookDragActive=true" @dragover.prevent="workbookDragActive=true" @dragleave.prevent="workbookDragActive=false" @drop.prevent="dropWorkbook"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M12 16V4m-4 4 4-4 4 4M5 14v5h14v-5"/></svg><strong>{{workbookBusy?'Validating workbook…':'Choose or drop an Excel gradesheet'}}</strong><span>`.xlsx` only · Maximum 5 MB</span></div>
    <p v-if="workbookFileName" class="workbook-selected-file"><strong>Selected file:</strong> {{workbookFileName}}</p>
    <div v-if="workbookBusy" class="workbook-progress-status" role="status" aria-live="polite"><span></span>Checking file structure, signed metadata, roster, assessments, and scores…</div>
    <div v-if="workbookPreviewError" class="workbook-inline-error" role="alert"><strong>Upload could not be previewed</strong><p>{{workbookPreviewError}}</p></div>
    <footer><button type="button" :disabled="workbookBusy" @click="goWorkbookStep(2)">Back</button><button type="button" :disabled="workbookBusy" @click="restartWorkbookFlow">Start over</button></footer>
  </section>

  <section v-else-if="workbookStep===4&&workbookPreview" class="workbook-step workbook-review">
    <div><span class="workbook-step-kicker">Step 4 of 5</span><h3 tabindex="-1" data-workbook-step-heading>Review Changes</h3><p><strong>{{workbookFileName}}</strong> · {{workbookPreview.apply_message}}</p></div>
    <dl class="workbook-preview-summary"><div v-for="(value,label) in workbookPreview.summary" :key="label"><dt>{{label.replaceAll('_',' ')}}</dt><dd>{{value}}</dd></div></dl>
    <div v-if="workbookPreview.blocking_errors.length" class="workbook-preview-blockers" role="alert"><strong>Import blocked</strong><ul><li v-for="message in workbookPreview.blocking_errors" :key="message">{{message}}</li></ul></div>
    <div v-if="workbookPreview.issues.length" class="workbook-preview-table-wrap"><h3>Validation failures</h3><table><thead><tr><th>Location</th><th>Issue</th></tr></thead><tbody><tr v-for="(item,index) in workbookPreview.issues" :key="`${item.cell||'workbook'}-${index}`"><td>{{item.cell||'Workbook'}}</td><td>{{item.message}}</td></tr></tbody></table></div>
    <div v-if="workbookPreview.changes.length" class="workbook-preview-table-wrap"><h3>Score comparison</h3><table><thead><tr><th>Student</th><th>Assessment</th><th>Current score</th><th>Imported score</th><th>Status</th></tr></thead><tbody><tr v-for="item in workbookPreview.changes" :key="`${item.enrollment_subject_id}-${item.assessment_id}`"><td><strong>{{item.student_name}}</strong><small>{{item.student_number}}</small></td><td>{{item.assessment}}</td><td>{{item.existing??'Blank'}}</td><td>{{item.imported}}</td><td><span class="workbook-change-status" :data-status="item.status">{{item.status}}</span></td></tr></tbody></table></div>
    <p v-if="!workbookPreview.changes.length&&!workbookPreview.issues.length" class="workbook-empty-review">No score changes were found. Blank cells leave current scores unchanged.</p>
    <footer><button type="button" @click="advanceWorkbookStep(3)">Upload another file</button><button type="button" @click="restartWorkbookFlow">Start over</button><button v-if="workbookPreview.can_apply&&!workbookPreview.blocking_errors.length" type="button" class="grading-button primary" :disabled="workbookProposalExpired" @click="advanceWorkbookStep(5)">Continue to Apply</button></footer>
  </section>

  <section v-else-if="workbookStep===5&&workbookPreview" class="workbook-step workbook-apply-step">
    <div><span class="workbook-step-kicker">Step 5 of 5</span><h3 tabindex="-1" data-workbook-step-heading>Apply Changes</h3><p>You are about to save <strong>{{workbookPreview.summary.proposed_changes}} score {{workbookPreview.summary.proposed_changes===1?'change':'changes'}}</strong> as grading drafts. This will not submit grades to the Registrar.</p></div>
    <div class="workbook-draft-boundary"><strong>Grade Submission remains separate</strong><p>Applying this workbook updates draft assessment scores only. Registrar submission still requires the existing Grade Submission workflow.</p></div>
    <div v-if="workbookProposalExpired" class="workbook-preview-blockers" role="alert"><strong>Preview expired</strong><p>This proposal is no longer active. Start over and upload the workbook again.</p></div>
    <div v-if="workbookApplyError" class="workbook-preview-blockers" role="alert"><strong>Scores were not reported as saved</strong><p>{{workbookApplyError}}</p></div>
    <footer><button type="button" :disabled="workbookBusy" @click="goWorkbookStep(4)">Back to Review</button><button type="button" :disabled="workbookBusy" @click="restartWorkbookFlow">Start over</button><button type="button" class="grading-button primary" :disabled="!canApplyWorkbook" @click="applyWorkbook">{{workbookBusy?'Applying score drafts…':'Confirm & Apply Score Drafts'}}</button></footer>
  </section>
</section>
<form v-else-if="modal==='assessment'" @submit.prevent="addAssessment"><label class="assessment-label-field"><span class="assessment-label-heading"><span>Label</span><button v-if="isWebsitePresentation&&!editingAssessment" type="button" @click="useNextAssessmentLabel">Use next available</button></span><input :value="assessmentForm.label" required maxlength="80" @input="updateAssessmentLabel($event.target.value)"><small v-if="isWebsitePresentation&&!editingAssessment">{{assessmentLabelIsAutomatic?'Suggested from the selected category. You can edit it.':'Custom label preserved when the category changes.'}}</small></label><label><span>Category</span><select :value="assessmentForm.category" @change="updateAssessmentCategory($event.target.value)"><option v-for="c in workspace.categories" :key="c">{{c}}</option></select></label><label><span>Maximum score</span><input v-model.number="assessmentForm.max_score" type="number" min=".01" step=".01" required></label><label><span>Order</span><input v-model.number="assessmentForm.display_order" type="number" min="1" required></label><footer><button type="button" @click="modal=''">Cancel</button><button class="grading-button primary" :disabled="saving">{{isWebsitePresentation&&editingAssessment?'Save changes':'Add Assessment'}}</button></footer></form>
<div v-else-if="reviewSheet" class="grading-review-detail"><section class="grading-summary"><div><small>Subject</small><strong>{{reviewSheet.section_subject.subject.subject_code}} — {{reviewSheet.section_subject.subject.subject_name}}</strong></div><div><small>Section</small><strong>{{reviewSheet.section_subject.section.section_name}}</strong></div><div><small>Professor</small><strong>{{reviewSheet.professor.user.profile.first_name}} {{reviewSheet.professor.user.profile.last_name}}</strong></div><div><small>Term</small><strong>{{reviewSheet.section_subject.section.academic_year.school_year}} · {{reviewSheet.section_subject.section.semester.semester_name}}</strong></div><div><small>Submitted</small><strong>{{fmt(reviewSheet.submitted_at)}}</strong></div><div><small>Status</small><strong>{{reviewSheet.status}}</strong></div></section><div class="grading-table-wrap"><table><thead><tr><th>Student Number</th><th>Student Name</th><th>Midterm</th><th>Finals</th><th>Final Grade</th><th>Grade Point</th><th>Remarks</th></tr></thead><tbody><tr v-for="student in reviewSheet.latest_submission.students" :key="student.id"><td>{{student.student_number}}</td><td>{{student.student_name}}</td><td>{{student.midterm_grade}}</td><td>{{student.finals_grade}}</td><td><strong>{{student.final_grade}}</strong></td><td>{{student.grade_point??'Not configured'}}</td><td>{{student.remarks??'Not configured'}}</td></tr></tbody></table></div><label v-if="reviewSheet.status==='submitted'">Return reason<textarea v-model.trim="returnReason" rows="3" maxlength="2000" placeholder="Explain what the Professor must correct"></textarea></label><footer><button v-if="['approved','published'].includes(reviewSheet.status)" type="button" :disabled="saving" @click="exportClass">Export CSV</button><template v-if="reviewSheet.status==='submitted'"><button type="button" :disabled="saving||returnReason.length<3" @click="reviewAction('return')">Reject &amp; Return</button><button type="button" class="grading-button primary" :disabled="saving" @click="reviewAction('approve')">Approve</button></template></footer></div></section></div>
</main></template>
